// Delta Exchange India live streaming markets
MARKET_DATA["BTCUSD"] = { name: "Bitcoin / USD (Delta)", category: "Delta", currency: "USD", symbol: "$", data: [] };
MARKET_DATA["ETHUSD"] = { name: "Ethereum / USD (Delta)", category: "Delta", currency: "USD", symbol: "$", data: [] };
MARKET_DATA["XAUTUSD"] = { name: "Gold Perpetual (Delta)", category: "Delta", currency: "USD", symbol: "$", data: [] };
MARKET_DATA["SOLUSD"] = { name: "Solana / USD (Delta)", category: "Delta", currency: "USD", symbol: "$", data: [] };
MARKET_DATA["XRPUSD"] = { name: "Ripple / USD (Delta)", category: "Delta", currency: "USD", symbol: "$", data: [] };

function parseMarketData() {
  const m = {JAN:0,FEB:1,MAR:2,APR:3,MAY:4,JUN:5,JUL:6,AUG:7,SEP:8,OCT:9,NOV:10,DEC:11};
  for (const k in MARKET_DATA) {
    if (!MARKET_DATA[k] || !MARKET_DATA[k].data) continue;
    MARKET_DATA[k].data = MARKET_DATA[k].data.map(r => {
      const p = r.d.split('-');
      return {
        date: new Date(parseInt(p[2]), m[p[1]], parseInt(p[0])),
        dateStr: r.d,
        open: parseFloat(r.o),
        high: parseFloat(r.h),
        low: parseFloat(r.l),
        close: parseFloat(r.c),
        volume: parseFloat(r.v) || 0,
        turnover: parseFloat(r.t) || 0
      };
    }).filter(r => !isNaN(r.close));
  }
}
parseMarketData();
if (typeof globalThis !== 'undefined') globalThis.MARKET_DATA = MARKET_DATA;
if (typeof window !== 'undefined') window.MARKET_DATA = MARKET_DATA;
